export type StringKeys = keyof typeof strings.en;

/** Localized string for a given user language (string keys only). */
export function t(lang: Language, key: StringKeys): string {
  const value = strings[lang][key];
  return typeof value === "string" ? value : (strings.en[key] as string);
}
